#!/usr/bin/env python3
"""Guarded consistency/documentation installer for labtools commit 5225d07."""
import argparse,base64,hashlib,json,os,subprocess,tempfile,zlib
from pathlib import Path
from uuid import uuid4
DATA=json.loads(zlib.decompress(base64.b64decode('')))
PAYLOAD={k:base64.b64decode(v) for k,v in DATA['payload'].items()}
def norm(d):return d.decode('utf-8-sig').replace('\r\n','\n').rstrip('\n').encode()
def sha(d):return hashlib.sha256(norm(d)).hexdigest()
def target(root,n):
 p=root/n
 if Path(n).is_absolute() or '..' in Path(n).parts or not p.resolve().is_relative_to(root):raise RuntimeError('Unsafe path: '+n)
 return p
def atomic(p,d):
 p.parent.mkdir(parents=True,exist_ok=True);fd,tmp=tempfile.mkstemp(prefix='.labtools-consistency-',dir=p.parent)
 try:
  with os.fdopen(fd,'wb') as f:f.write(d)
  os.replace(tmp,p)
 finally:Path(tmp).unlink(missing_ok=True)
def restore(root,originals):
 for n,v in originals.items():atomic(target(root,n),base64.b64decode(v))
def main():
 ap=argparse.ArgumentParser(description=__doc__);g=ap.add_mutually_exclusive_group(required=True)
 g.add_argument('--check',action='store_true');g.add_argument('--apply',action='store_true');g.add_argument('--rollback',type=Path)
 ap.add_argument('--root',type=Path,default=Path.cwd());ap.add_argument('--backup-dir',type=Path);a=ap.parse_args();root=a.root.resolve()
 def git(*x):return subprocess.check_output(['git','-C',str(root),*x],text=True).strip()
 if Path(git('rev-parse','--show-toplevel')).resolve()!=root:raise RuntimeError('Run from repository root')
 branch=git('symbolic-ref','--short','HEAD');head=git('rev-parse','HEAD')
 if branch in {'main','master'}:raise RuntimeError('Refusing main/master')
 if a.rollback:
  rec=json.loads((a.rollback/'backup.json').read_text())
  if rec['root']!=str(root) or set(rec['originals'])!=set(PAYLOAD):raise RuntimeError('Backup mismatch')
  for n,d in PAYLOAD.items():
   p=target(root,n)
   if p.read_bytes()!=d:raise RuntimeError('Rollback would overwrite later edits: '+n)
  restore(root,rec['originals']);print('Rollback completed; Git unchanged.');return
 errors=[]
 for n,h in DATA['baseline'].items():
  p=target(root,n)
  if not p.is_file() or sha(p.read_bytes())!=h:errors.append('Baseline mismatch: '+n)
 if errors:raise RuntimeError('\n'.join(errors))
 print(f'Baseline matches; branch {branch}; HEAD {head[:12]}; {len(PAYLOAD)} files.')
 if a.check:print('CHECK ONLY: no files changed.');return
 bd=(a.backup_dir or root.parent/'.labtools-backups').resolve()
 if bd.is_relative_to(root):raise RuntimeError('Backup must be outside repository')
 backup=bd/(root.name+'-consistency-'+uuid4().hex);backup.mkdir(parents=True)
 originals={n:base64.b64encode(target(root,n).read_bytes()).decode() for n in PAYLOAD}
 (backup/'backup.json').write_text(json.dumps({'root':str(root),'originals':originals},indent=2))
 try:
  for n,d in PAYLOAD.items():atomic(target(root,n),d)
 except BaseException:
  restore(root,originals);raise
 print('APPLIED. Backup: '+str(backup));print('No files staged, committed, or switched.')
if __name__=='__main__':
 try:main()
 except Exception as exc:raise SystemExit('ERROR: '+str(exc))
